def aplicar_estado(compra, estado_pago):
    """Aplica el estado de un pago de Cobrá a la compra. Es idempotente."""
    nuevo = ESTADOS_PAGO.get(estado_pago)
    if nuevo is None or not db.resolver_compra(compra['id'], nuevo):
        return
    if nuevo == 'aprobada':
        socio = db.socio(compra['socio_id'])
        correo.enviar(socio['email'], 'Compra de créditos aprobada',
                      f"Hola {socio['nombre']}, tu compra de {compra['creditos']} créditos fue aprobada.")


def compra_de_referencia(referencia):
    m = re.fullmatch(r'pulso-compra-(\d+)', referencia if isinstance(referencia, str) else '')
    return db.compra(int(m.group(1))) if m else None


